class Solution {
    public int[] getBiggestThree(int[][] grid){
        int rows=grid.length,cols=grid[0].length;
        TreeSet<Integer> sums=new TreeSet<>(Collections.reverseOrder());
        for(int row=0;row<rows;row++)for(int col=0;col<cols;col++){
            sums.add(grid[row][col]);
            for(int radius=1;row+2*radius<rows&&col-radius>=0&&col+radius<cols;radius++){
                int sum=0;
                for(int step=0;step<radius;step++)sum+=grid[row+step][col+step]+grid[row+radius+step][col+radius-step]+grid[row+2*radius-step][col-step]+grid[row+radius-step][col-radius+step];
                sums.add(sum);
            }
        }
        int[] answer=new int[Math.min(3,sums.size())];
        int index=0;
        for(int sum:sums){
            if(index==answer.length)break;
            answer[index++]=sum;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun getBiggestThree(grid:Array<IntArray>):IntArray{
        val rows=grid.size;
        val cols=grid[0].size;
        val sums=java.util.TreeSet<Int>(compareByDescending{
            it
        });
        for(row in 0 until rows)for(col in 0 until cols){
            sums.add(grid[row][col]);
            var radius=1;
            while(row+2*radius<rows&&col-radius>=0&&col+radius<cols){
                var sum=0;
                for(step in 0 until radius)sum+=grid[row+step][col+step]+grid[row+radius+step][col+radius-step]+grid[row+2*radius-step][col-step]+grid[row+radius-step][col-radius+step];
                sums.add(sum);
                radius++
            }
        };
        return sums.take(3).toIntArray()
    }
}

